  ('zcrm_5797994000003172074', 'Ambrook', 'Ambrook', 'Roman Sofman', 'Mackenzie Burnett', 'Ambrook offers specialized accounting software for family-run farms, ranches, and agribusinesses. The platform includes bookkeeping, invoicing, bill payment, and analytics tools. Ambrook aims to help these businesses manage finances, track profitability, and prepare for the future.', 'HV Genesis', 'Financial Innovation', 'Spring 2025', NULL, 'Reached Out', 'Roman Sofman', 'Rejected', 'Financial Innovation', NULL, NULL, '2025-08-26 06:46:00', '2025-10-28 12:43:34', '2025-10-28 12:43:43'),
